function AVLNode(key){ this.key=key; this.left=null; this.right=null; this.h=1; }
function h(n){ return n?n.h:0; }
function upd(n){ n.h=1+Math.max(h(n.left),h(n.right)); return n; }
function bf(n){ return h(n.left)-h(n.right); }
function rotateRight(y){ var x=y.left; var t=x.right; x.right=y; y.left=t; upd(y); upd(x); return x; }
function rotateLeft(x){ var y=x.right; var t=y.left; y.left=x; x.right=t; upd(x); upd(y); return y; }
function insert(node,key){ if(!node) return new AVLNode(key); if(key<node.key) node.left=insert(node.left,key); else if(key>node.key) node.right=insert(node.right,key); else return node; node=upd(node); var b=bf(node); if(b>1 && key<node.left.key) return rotateRight(node); if(b<-1 && key>node.right.key) return rotateLeft(node); if(b>1 && key>node.left.key){ node.left=rotateLeft(node.left); return rotateRight(node); } if(b<-1 && key<node.right.key){ node.right=rotateRight(node.right); return rotateLeft(node); } return node; }
function inorder(node,out){ if(!node) return; inorder(node.left,out); out.push(node.key); inorder(node.right,out); }
function height(node){ return h(node); }
function makeAVL(){ return {root:null, add:function(k){ this.root=insert(this.root,k); }, list:function(){ var o=[]; inorder(this.root,o); return o; }, h:function(){ return height(this.root); }}; }
var EXPORTS={makeAVL:makeAVL, insert:insert, height:height};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AvlTreeForgePure = EXPORTS; }
